cli-convert.calor:
§M{Report:overflow=unchecked}
  §U{System}
  §U{System.Text}

  §NS{_global:global}
    §M{Report:pub}
      §F{Line:pub} (str:item, f64:amount) -> str
        §R "${item,-8}|${amount,10:F2}"

      §F{Kind:pub} (FormattableString:f) -> str
        §R (+ "fs:" f.Format)

      §F{Kind:pub} (any:o) -> str
        §R (+ "object:" o)

      §F{Pick:pub} (i32:x) -> str
        §R §C{Kind} (cast global::System.FormattableString "k=${x}")

      §F{Build:pub} (i32:x) -> str
        §B{sb} (sb-new)
        §RAW
        sb.Append($"x={x}");
        §/RAW
        §R (sb-tostring sb)

